from bioblend.galaxy import GalaxyInstance
from pathlib import Path
import json
key=Path('/run/secrets/galaxy_api_key').read_text().strip()
gi=GalaxyInstance('https://usegalaxy.org', key=key)
t=gi.tools.show_tool('toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy3', io_details=True, link_details=True)
# write schema locally for inspection (tool metadata, not data)
out='/workspace/deseq2_tool_schema.json'
open(out,'w').write(json.dumps(t, indent=2))
print(out)
print('top keys', t.keys())
# compact names

def walk(x, path=''):
    if isinstance(x, dict):
        name=x.get('name')
        typ=x.get('type')
        if name or typ:
            print(path, 'name=', name, 'type=', typ, 'label=', x.get('label'))
        if x.get('type')=='conditional':
            for c in x.get('cases',[]):
                print(path+'/'+str(name), 'CASE', c.get('value'))
                for inp in c.get('inputs',[]): walk(inp, path+'/'+str(name)+'='+str(c.get('value')))
        elif x.get('type') in ('repeat','section'):
            for inp in x.get('inputs',[]): walk(inp, path+'/'+str(name))
        else:
            for key2 in ('inputs','cases'):
                if key2 in x and isinstance(x[key2], list):
                    for i, v in enumerate(x[key2]): walk(v, path+'/'+str(name or key2))
for inp in t['inputs']:
    walk(inp)
PY"

